'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var Complex64 = require( '@stdlib/complex-float32-ctor' );
var randu = require( '@stdlib/random-base-randu' );
var isnanf = require( '@stdlib/math-base-assert-is-nanf' );
var pkg = require( './../package.json' ).name;
var imag = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var values;
	var im;
	var i;

	values = [
		new Complex64( randu(), randu() ),
		new Complex64( randu(), randu() ),
		new Complex64( randu(), randu() )
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		im = imag( values[ i%values.length ] );
		if ( isnanf( im ) ) {
			b.fail( 'should not return NaN' );
		}
	}
	b.toc();
	if ( isnanf( im ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":57,"totalLines":57,"truncated":false}},"title":"repos/pc-lib-3456/complex-float32-imag/benchmark/benchmark.js","time":{"start":1783264312489,"end":1783264312493}},"id":"prt_f32d5fb8f001EmF5r3tHBQsbQV","sessionID":"ses_0cd2a7adeffeXGrQh7EW178KDq","messageID":"msg_f32d5f08b001o1CiEbFeTOSOvp"}}

